import * as React from "react";
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/*
 * Ops Sharp Button — the precise graphite control of a developer ops surface.
 *
 * The hero (`default`) is the solid near-black tile: graphite fill, a hairline
 * top highlight, a tight contact drop, and a 1px rim (--shadow-primary). It is
 * the same material the active sidebar tile + filled controls wear. Secondary
 * is a crisp white panel button with a hairline border; outline/ghost stay
 * understated for a dense toolbar.
 */

const buttonVariants = cva(
  [
    "relative inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "text-sm font-medium",
    "rounded-md transition-[background-color,box-shadow,border-color,transform] duration-fast ease-out",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-1 focus-visible:ring-offset-background",
    "disabled:pointer-events-none disabled:opacity-50",
    "active:translate-y-px",
  ].join(" "),
  {
    variants: {
      variant: {
        // Hero — solid graphite tile.
        default:
          "bg-primary text-primary-foreground [box-shadow:var(--shadow-primary)] " +
          "hover:bg-primary/90",
        // Same material under an explicit name for showcases that ask for it.
        primary:
          "bg-primary text-primary-foreground [box-shadow:var(--shadow-primary)] " +
          "hover:bg-primary/90",
        // Secondary — crisp white panel button.
        secondary:
          "bg-card text-secondary-foreground border border-border [box-shadow:var(--shadow-s)] " +
          "hover:bg-secondary hover:border-ring/30",
        // Outline — transparent with a full hairline border.
        outline:
          "border border-border bg-transparent text-foreground " +
          "hover:bg-secondary hover:border-ring/30",
        // Ghost — no chrome, understated toolbar action.
        ghost:
          "bg-transparent text-muted-foreground " +
          "hover:bg-secondary hover:text-foreground",
        // Destructive.
        destructive:
          "bg-destructive text-destructive-foreground [box-shadow:var(--shadow-s)] " +
          "hover:bg-destructive/90",
        // Link.
        link: "text-foreground underline-offset-4 hover:underline",
      },
      size: {
        sm: "h-8 px-3 text-xs",
        default: "h-9 px-4",
        lg: "h-10 px-6 text-sm",
        icon: "h-9 w-9",
        "icon-sm": "h-8 w-8",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends Omit<ButtonPrimitive.Props, "className">,
    VariantProps<typeof buttonVariants> {
  className?: string;
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    // Callers written against the Radix API pass the element to become as a
    // child: <Button asChild><Link>…</Link></Button>. Base UI has no asChild,
    // it composes through `render`. Without this the prop reaches the DOM and
    // the anchor nests inside the button instead of replacing it, which stacks
    // the icon above the label and puts a link inside a button.
    if (asChild && React.isValidElement(props.children)) {
      const { children, ...rest } = props
      return (
        <ButtonPrimitive
          ref={ref}
          className={cn(buttonVariants({ variant, size, className }))}
          {...rest}
          // After the spread, so an explicit asChild child wins over a stray
          // render prop rather than being silently replaced by it.
          // SAFETY: this branch runs only when `asChild` is set, and the caller then
          // owns passing a single element for the slot to clone.
          render={children as React.ReactElement}
        />
      );
    }

    return (
      <ButtonPrimitive
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };
